/**
 * job_device_mapper.c — framework for rank→device mapping.
 *
 * Provides:
 *   - device_map_init / add_entry / flush_to_file / destroy
 *   - WEAK map_job_to_device stub (no-op by default)
 *
 * The strong override lives in mapper_generated.c (generated by
 * scripts/register_job_device_mapper.sh) and compiled into
 * bin/libs/libjob_device_mapper.so.
 *
 * MPI-dependent paths are guarded by HAVE_MPI.  When MPI is not
 * available device_map_flush_to_file becomes a no-op.
 */

#include "job_device_mapper.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#ifdef HAVE_MPI
#include <mpi.h>
#endif

/* ── Framework API ────────────────────────────────────────────────── */

void device_map_init(device_map_ctx_t *ctx, int rank, int size)
{
    ctx->rank         = rank;
    ctx->size         = size;
    ctx->num_entries  = 0;
}

int device_map_add_entry(device_map_ctx_t *ctx,
                         const char *device_type, int device_number)
{
    if (ctx->num_entries >= DEVICE_MAP_MAX_ENTRIES)
        return -1;

    device_map_entry_t *e = &ctx->entries[ctx->num_entries];
    e->rank = ctx->rank;

    if (gethostname(e->node, sizeof(e->node)) != 0)
        snprintf(e->node, sizeof(e->node), "unknown");
    e->node[sizeof(e->node) - 1] = '\0';

    snprintf(e->device_type, sizeof(e->device_type), "%s", device_type);
    e->device_number = device_number;

    ctx->num_entries++;
    return 0;
}

void device_map_flush_to_file(device_map_ctx_t *ctx)
{
#ifdef HAVE_MPI
    if (!ctx) return;

    int *recvcounts = NULL;
    int *displs      = NULL;
    unsigned char *all_entries = NULL;

    /* 1. Gather entry counts from every rank */
    if (ctx->rank == 0) {
        recvcounts = (int *)malloc((size_t)ctx->size * sizeof(int));
        displs     = (int *)malloc((size_t)ctx->size * sizeof(int));
    }

    PMPI_Gather(&ctx->num_entries, 1, MPI_INT,
                recvcounts, 1, MPI_INT, 0, MPI_COMM_WORLD);

    /* 2. Gatherv variable-length entry arrays */
    int total_entries = 0;
    if (ctx->rank == 0) {
        int byte_off = 0;
        for (int i = 0; i < ctx->size; i++) {
            displs[i]      = byte_off;
            int nbytes     = recvcounts[i] * (int)sizeof(device_map_entry_t);
            recvcounts[i]  = nbytes;
            byte_off      += nbytes;
        }
        total_entries = byte_off / (int)sizeof(device_map_entry_t);
        if (byte_off > 0)
            all_entries = (unsigned char *)malloc((size_t)byte_off);
    }

    int send_bytes = ctx->num_entries * (int)sizeof(device_map_entry_t);
    PMPI_Gatherv(ctx->entries, send_bytes, MPI_BYTE,
                 all_entries, recvcounts, displs, MPI_BYTE,
                 0, MPI_COMM_WORLD);

    /* 3. Rank 0 writes CSV */
    if (ctx->rank == 0 && total_entries > 0 && all_entries) {
        const char *outdir = getenv("PERF_OUTPUT_DIR");
        if (!outdir || !outdir[0]) outdir = "perf_files";

        char path[512];
        snprintf(path, sizeof(path), "%s/map.csv", outdir);

        FILE *fp = fopen(path, "w");
        if (fp) {
            fprintf(fp, "rank,node,device_type,device_number\n");
            device_map_entry_t *arr = (device_map_entry_t *)all_entries;
            for (int i = 0; i < total_entries; i++) {
                fprintf(fp, "%d,%s,%s,%d\n",
                        arr[i].rank, arr[i].node,
                        arr[i].device_type, arr[i].device_number);
            }
            fclose(fp);
        } else {
            fprintf(stderr, "[device_map] failed to write %s\n", path);
        }
    }

    free(all_entries);
    free(recvcounts);
    free(displs);
#else
    (void)ctx;
#endif
}

void device_map_destroy(device_map_ctx_t *ctx)
{
    (void)ctx;   /* nothing to free (entries are inline in the struct) */
}

/* ── Weak default: no-op ────────────────────────────────────────────
 *
 * This is the fallback when no libjob_device_mapper.so is loaded.
 * The generated mapper_generated.c provides a strong override that
 * calls each user-registered mapper function.
 */
__attribute__((weak)) void map_job_to_device(device_map_ctx_t *ctx)
{
    (void)ctx;
}
